// src/db.js
const all=async(db,sql,...args)=>(await db.prepare(sql).bind(...args).all()).results;
const first=async(db,sql,...args)=>db.prepare(sql).bind(...args).first();
const run=(db,sql,...args)=>db.prepare(sql).bind(...args).run();
const statement=(db,sql,...args)=>db.prepare(sql).bind(...args);
async function stage(db,runId,kind,key,data) {
  await run(db,'INSERT INTO stage(run_id,kind,key,data) VALUES(?,?,?,?) ON CONFLICT(run_id,kind,key) DO UPDATE SET data=excluded.data',runId,kind,key,JSON.stringify(data));
}

async function stageMany(db,runId,kind,items) {
  for(let i=0;i<items.length;i+=50){
    await db.batch(items.slice(i,i+50).map(({key,data})=>statement(db,'INSERT INTO stage(run_id,kind,key,data) VALUES(?,?,?,?) ON CONFLICT(run_id,kind,key) DO UPDATE SET data=excluded.data',runId,kind,key,JSON.stringify(data))));
  }
}


// src/connectors/http.js
// This module is the ONLY upstream transport. No method parameter is accepted.
class UpstreamError extends Error {
  constructor(code,retryAfter=0) { super(code);this.retryAfter=retryAfter; }
}
async function readJSON(url, {origin,token,headers={},fetcher=fetch}) {
  const u=new URL(url);
  if(u.origin!==origin || u.protocol!=='https:' || u.username || u.password || u.searchParams.has('access_token')) throw new UpstreamError('UPSTREAM_ORIGIN_BLOCKED');
  let response;
  try { response=await fetcher(u.href,{method:'GET',redirect:'error',headers:{Accept:'application/json',...headers,Authorization:`Bearer ${token}`},signal:AbortSignal.timeout(25000)}); }
  catch { throw new UpstreamError('UPSTREAM_NETWORK_ERROR'); }
  if (!response.ok) {
    const retry=Math.min(3600,Math.max(0,Number(response.headers.get('retry-after'))||0));
    throw new UpstreamError(`UPSTREAM_HTTP_${response.status}`,retry);
  }
  if (Number(response.headers.get('content-length'))>12000000) throw new UpstreamError('UPSTREAM_RESPONSE_TOO_LARGE');
  // Do not log response bodies: CRM data may contain health information.
  let data;try { data=await response.json(); } catch {throw new UpstreamError('UPSTREAM_INVALID_JSON');}
  if(data?.error) throw new UpstreamError('UPSTREAM_API_ERROR');
  return data;
}
function nextCursor(data,origin,accountId) {
  const next=data?.paging?.next;
  if(!next) return null;
  const u=new URL(next);
  if(u.origin!==origin || !u.pathname.includes(`/act_${accountId}/`)) throw new UpstreamError('META_PAGINATION_SCOPE_BLOCKED');
  const after=data?.paging?.cursors?.after || u.searchParams.get('after');
  if(!after || after.length>4000) throw new UpstreamError('META_INVALID_CURSOR');
  // Never persist paging.next, which may contain an access token.
  return after;
}


// src/domain.js
const TZ = 'America/Sao_Paulo';
function daySP(value = new Date()) {
  const date = value instanceof Date ? value : new Date(value);
  if (!Number.isFinite(date.getTime())) throw new Error('INVALID_DATE');
  return new Intl.DateTimeFormat('en-CA', {timeZone: TZ, year:'numeric', month:'2-digit', day:'2-digit'}).format(date);
}
function addDays(day, n) { return new Date(Date.parse(`${day}T12:00:00Z`) + n * 86400000).toISOString().slice(0,10); }
function validateRange(start, end, now = new Date()) {
  const valid = d => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && !Number.isNaN(Date.parse(d)) && new Date(`${d}T12:00:00Z`).toISOString().slice(0,10) === d;
  if (!valid(start) || !valid(end) || start > end || end > daySP(now)) throw new Error('INVALID_RANGE');
  if ((Date.parse(end)-Date.parse(start))/86400000 > 1095) throw new Error('RANGE_TOO_LONG');
  return {start, end};
}
function presetRange(preset, today = daySP()) {
  let start=today,end=today;
  if (preset==='yesterday') start=end=addDays(today,-1);
  if (preset==='7') start=addDays(today,-6);
  if (preset==='30') start=addDays(today,-29);
  if (preset==='month') start=today.slice(0,8)+'01';
  if (preset==='lastMonth') { end=addDays(today.slice(0,8)+'01',-1);start=end.slice(0,8)+'01'; }
  return {start,end};
}
const ratio = (a,b,m=1) => a === null || a === undefined || !b ? null : a / b * m;
function pickContacts(events, start, end, filters={}) {
  const first = new Map();
  for (const e of events) {
    if (e.day<start || e.day>end) continue;
    const old=first.get(e.contactId);
    if (!old || e.at<old.at || (e.at===old.at && e.id<old.id)) first.set(e.contactId,e);
  }
  return [...first.values()].filter(e=>(!filters.campaign || (e.campaignId||'unknown')===filters.campaign) && (!filters.ad || e.adId===filters.ad));
}
function aggregateMetrics(rows, conversationsAvailable = true) {
  if (!rows) return {spend:null,impressions:null,clicks:null,conversations:null,cpc:null,ctr:null,cpm:null,costConversation:null};
  const sum=k=>rows.reduce((s,r)=>s+Number(r[k]||0),0);
  const spend=sum('spend'), impressions=sum('impressions'),clicks=sum('clicks');
  const conversations=conversationsAvailable ? sum('conversations') : null;
  return {spend,impressions,clicks,conversations,cpc:ratio(spend,clicks),ctr:ratio(clicks,impressions,100),cpm:ratio(spend,impressions,1000),costConversation:ratio(spend,conversations)};
}
function metaActions(actions, actionType) {
  const matches=(actions||[]).filter(x=>x.action_type===actionType);
  if (matches.length>1) throw new Error('META_OVERLAPPING_ACTIONS');
  const n=matches.length?Number(matches[0].value):0;
  if (!Number.isFinite(n)||n<0) throw new Error('META_INVALID_METRIC');
  return n;
}
function getPath(value,path) {
  if (!path) return undefined;
  return path.split('.').reduce((v,k)=>v?.[k],value);
}
function safeId(value) {
  if (typeof value!=='number' && typeof value!=='string') return null;
  const s=String(value); return /^[A-Za-z0-9_:-]{1,160}$/.test(s)?s:null;
}
function timestamp(value, unit='iso') {
  if (value===null || value===undefined || value==='') return null;
  const date=new Date(unit==='seconds'?Number(value)*1000:unit==='milliseconds'?Number(value):value);
  return Number.isFinite(date.getTime())?date.toISOString():null;
}
async function digest(value) {
  return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('');
}
async function pseudonym(key,value) {
  if (!key || key.length<32) throw new Error('PSEUDONYM_KEY_REQUIRED');
  const k=await crypto.subtle.importKey('raw',new TextEncoder().encode(key),{name:'HMAC',hash:'SHA-256'},false,['sign']);
  return [...new Uint8Array(await crypto.subtle.sign('HMAC',k,new TextEncoder().encode(String(value))))].map(x=>x.toString(16).padStart(2,'0')).join('');
}


// src/connectors/rugido.js


const ORIGIN='https://clientcrm-api.rugido.com';
// Field paths MUST be confirmed against a real, authorized Eccoa response.
function crmConfig(env) {
  if(env.CRM_API_ORIGIN_APPROVED!=='true') throw new Error('CRM_ORIGIN_NOT_APPROVED');
  if(!env.CRM_TOKEN||!safeId(env.CRM_WORKSPACE_ID)||!env.CRM_WORKSPACE_NAME||!env.PSEUDONYM_KEY) throw new Error('CRM_CONFIGURATION_REQUIRED');
  let s;try{s=JSON.parse(env.CRM_SCHEMA_JSON);}catch{throw new Error('CRM_SCHEMA_NOT_VALIDATED');}
  if(s.validated!==true||!s.contacts||!s.conversations||!s.messages||!s.workspace||!s.evidence||!s.stageNames) throw new Error('CRM_SCHEMA_NOT_VALIDATED');
  return s;
}
async function crmRead(env,path,params={}) {
  if(env.CRM_API_ORIGIN_APPROVED!=='true') throw new Error('CRM_ORIGIN_NOT_APPROVED');
  if(!/^\/(workspaces\/current|contacts|conversations(?:\/[A-Za-z0-9_-]+\/messages)?)$/.test(path)) throw new Error('CRM_ENDPOINT_BLOCKED');
  const u=new URL(`/api/v1${path}`,ORIGIN);
  for(const [k,v] of Object.entries(params))if(v!==null&&v!==undefined)u.searchParams.set(k,String(v));
  return readJSON(u,{origin:ORIGIN,token:env.CRM_TOKEN,headers:{'X-Workspace-Id':env.CRM_WORKSPACE_ID}});
}
async function verifyWorkspace(env,s) {
  const data=await crmRead(env,'/workspaces/current');
  const id=String(getPath(data,s.workspace.id)||'');const name=getPath(data,s.workspace.name);
  if(id!==env.CRM_WORKSPACE_ID||name!==env.CRM_WORKSPACE_NAME)throw new Error('CRM_WORKSPACE_MISMATCH');
  return {id,name,origin:ORIGIN,schemaConfirmed:true};
}
function pageItems(data,s,page) {
  const items=getPath(data,s.items);
  const total=Number(getPath(data,s.total));
  if(!Array.isArray(items)||!Number.isInteger(total)||total<0)throw new Error('CRM_PAGINATION_SCHEMA_MISMATCH');
  const per=s.perPage||100;
  if(items.length>per||(items.length!==per&&page*per<total))throw new Error('CRM_PAGINATION_INCOMPLETE');
  return {items,total,next:page*per<total?page+1:null};
}
async function projectContact(raw,s,key) {
  const id=safeId(getPath(raw,s.id));if(!id)throw new Error('CRM_CONTACT_ID_MISSING');
  const stageId=safeId(getPath(raw,s.stageId));
  // Store only labels from the validated pipeline dictionary, never free patient fields.
  const stageName=stageId&&s.stageNames?.[stageId]||'Etapa não informada';
  const undated=s.paidFlag ? getPath(raw,s.paidFlag)===s.paidValue : false;
  return {id:await pseudonym(key,id),stageId,stageName,undated};
}
async function projectEvent(raw,s,key) {
  const id=safeId(getPath(raw,s.id)), contactId=safeId(getPath(raw,s.contactId));
  if(!id)throw new Error('CRM_MESSAGE_ID_MISSING');
  // Require inbound + an explicit verified paid-evidence field. Never parse message text.
  if(getPath(raw,s.direction)!==s.incomingValue||getPath(raw,s.paidProof)!==s.paidValue)return null;
  if(!contactId)throw new Error('CRM_EVENT_CONTACT_MISSING');
  const at=timestamp(getPath(raw,s.timestamp),s.timestampUnit);
  const adId=safeId(getPath(raw,s.adId));
  const campaignId=safeId(getPath(raw,s.campaignId));
  const adsetId=safeId(getPath(raw,s.adsetId));
  const contact=await pseudonym(key,contactId);
  if(!at)return {undatedContact:contact};
  return {id:await pseudonym(key,`message:${id}`),contactId:contact,at,day:daySP(at),campaignId,adsetId,adId,evidence:'Mensagem recebida com referência paga'};
}
function messagePage(data,s) {
  const items=getPath(data,s.items);
  if(!Array.isArray(items))throw new Error('CRM_MESSAGES_SCHEMA_MISMATCH');
  const hasMore=getPath(data,s.hasMore);
  if(typeof hasMore!=='boolean')throw new Error('CRM_MESSAGES_PAGINATION_UNVERIFIED');
  const next=hasMore?getPath(data,s.nextCursor):null;
  if(hasMore&&!next)throw new Error('CRM_MESSAGES_CURSOR_MISSING');
  return {items,next};
}


// src/connectors/meta.js


const META_ORIGIN='https://graph.facebook.com';
function metaConfig(env) {
  if(!env.META_TOKEN||!/^\d+$/.test(env.META_ACCOUNT_ID||'')||!/^v\d+\.0$/.test(env.META_API_VERSION||'')||!/^\d{4}-\d{2}-\d{2}$/.test(env.HISTORY_START||''))throw new Error('META_CONFIGURATION_REQUIRED');
}
async function metaRead(env,edge,params={}) {
  metaConfig(env);
  if(!['','/ads','/insights'].includes(edge))throw new Error('META_ENDPOINT_BLOCKED');
  const u=new URL(`/${env.META_API_VERSION}/act_${env.META_ACCOUNT_ID}${edge}`,META_ORIGIN);
  for(const [k,v] of Object.entries(params))if(v!==null&&v!==undefined)u.searchParams.set(k,typeof v==='object'?JSON.stringify(v):String(v));
  return readJSON(u,{origin:META_ORIGIN,token:env.META_TOKEN});
}
async function verifyMeta(env) {
  const a=await metaRead(env,'',{fields:'id,name,currency,timezone_name,account_status'});
  if(a.id!==`act_${env.META_ACCOUNT_ID}`||a.name!==env.META_ACCOUNT_NAME)throw new Error('META_ACCOUNT_MISMATCH');
  if(a.timezone_name!=='America/Sao_Paulo'||a.currency!=='BRL')throw new Error('META_TIMEZONE_OR_CURRENCY_MISMATCH');
  return {id:a.id,name:a.name,currency:a.currency,timezone:a.timezone_name,version:env.META_API_VERSION,attribution:'use_unified_attribution_setting=true',action:env.META_CONVERSATION_ACTION,conversationsValidated:env.META_METRIC_VALIDATED==='true'};
}
async function adsPage(env,after) {
  const data=await metaRead(env,'/ads',{fields:'id,name,status,effective_status,campaign{id,name},adset{id,name,attribution_spec},creative{id,object_type}',limit:100,after});
  if(!Array.isArray(data.data))throw new Error('META_ADS_SCHEMA_MISMATCH');
  const ads=data.data.map(a=>({id:a.id,name:a.name,campaignId:a.campaign?.id,campaignName:a.campaign?.name,adsetId:a.adset?.id,adsetName:a.adset?.name,status:a.effective_status||a.status,format:a.creative?.object_type||null,attribution:a.adset?.attribution_spec||null,preview:null}));
  if(ads.some(a=>!a.id||!a.campaignId||!a.adsetId))throw new Error('META_AD_HIERARCHY_MISSING');
  return {items:ads,next:nextCursor(data,META_ORIGIN,env.META_ACCOUNT_ID)};
}
async function insightPage(env,start,end,after) {
  const d=await metaRead(env,'/insights',{fields:'account_id,ad_id,ad_name,adset_id,adset_name,campaign_id,campaign_name,spend,impressions,inline_link_clicks,actions,date_start,date_stop',level:'ad',time_range:{since:start,until:end},time_increment:1,use_unified_attribution_setting:true,action_report_time:'impression',limit:250,after});
  if(!Array.isArray(d.data))throw new Error('META_INSIGHTS_SCHEMA_MISMATCH');
  const items=d.data.map(r=>{
    if(r.account_id!==env.META_ACCOUNT_ID||r.date_start!==r.date_stop||r.date_start<start||r.date_start>end)throw new Error('META_SCOPE_MISMATCH');
    const number=k=>{const n=Number(r[k]||0);if(!Number.isFinite(n)||n<0)throw new Error('META_INVALID_METRIC');return n;};
    return {day:r.date_start,adId:r.ad_id,adName:r.ad_name,campaignId:r.campaign_id,campaignName:r.campaign_name,adsetId:r.adset_id,adsetName:r.adset_name,spend:number('spend'),impressions:number('impressions'),clicks:number('inline_link_clicks'),conversations:env.META_METRIC_VALIDATED==='true'?metaActions(r.actions,env.META_CONVERSATION_ACTION):null};
  });
  return {items,next:nextCursor(d,META_ORIGIN,env.META_ACCOUNT_ID)};
}
function syncRange(env,confirmed) {
  const end=daySP();const start=confirmed? [env.HISTORY_START,addDays(end,-35)].sort().at(-1):env.HISTORY_START;
  if(start>end)throw new Error('META_HISTORY_START_IN_FUTURE');
  return {start,end};
}


// src/sync.js




async function startCycle(env,scheduledAt=new Date().toISOString()) {
  await run(env.ECCOA_DB,"INSERT INTO settings(key,value) VALUES('lastCron',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",scheduledAt);
  for(const provider of ['crm','meta']) {
    const active=await first(env.ECCOA_DB,"SELECT id FROM runs WHERE provider=? AND state='running'",provider);
    if(active){await env.ECCOA_JOBS.send({runId:active.id,provider});continue;}
    try {if(provider==='crm')crmConfig(env);else metaConfig(env);}
    catch(e){await run(env.ECCOA_DB,'UPDATE sources SET error=? WHERE provider=?',safeError(e),provider);continue;}
    const id=crypto.randomUUID();
    try {
      await env.ECCOA_DB.batch([
        statement(env.ECCOA_DB,"INSERT INTO runs(id,provider,state,cursor_json,started_at) VALUES(?,?,'running','{}',?)",id,provider,scheduledAt),
        statement(env.ECCOA_DB,'UPDATE sources SET active_run=?,started_at=?,error=NULL WHERE provider=?',id,scheduledAt,provider)
      ]);
    } catch {continue;} // Unique active-run index is the cross-invocation lock.
    await env.ECCOA_JOBS.send({runId:id,provider});
  }
  await env.ECCOA_DB.batch([
    statement(env.ECCOA_DB,'DELETE FROM sessions WHERE expires<?',Date.now()),
    statement(env.ECCOA_DB,'DELETE FROM attempts WHERE expires<?',Date.now()),
    statement(env.ECCOA_DB,"DELETE FROM stage WHERE run_id IN (SELECT id FROM runs WHERE state<>'running' AND started_at<?)",new Date(Date.now()-7*86400000).toISOString())
  ]);
}
function safeError(e) {
  return /^[A-Z][A-Z0-9_]{2,90}$/.test(e?.message||'')?e.message:'SYNC_INTERNAL_ERROR';
}
async function processJob(env,body) {
  if(!['crm','meta'].includes(body?.provider)||!/^[\da-f-]{36}$/.test(body?.runId||''))return;
  const db=env.ECCOA_DB,owner=crypto.randomUUID(),now=Date.now();
  const claimed=await run(db,"UPDATE runs SET lease_owner=?,lease_until=? WHERE id=? AND provider=? AND state='running' AND lease_until<?",owner,now+90000,body.runId,body.provider,now);
  if(!claimed.meta.changes)return;
  const job=await first(db,'SELECT * FROM runs WHERE id=?',body.runId);
  let cursor=JSON.parse(job.cursor_json);
  try {
    cursor=body.provider==='crm'?await crmStep(env,job,cursor):await metaStep(env,job,cursor);
    if(cursor.done) await publishRun(env,job,cursor);
    else {
      await run(db,'UPDATE runs SET cursor_json=?,pages=pages+1,retries=0,lease_until=0,lease_owner=NULL WHERE id=? AND lease_owner=?',JSON.stringify(cursor),job.id,owner);
      await env.ECCOA_JOBS.send(body);
    }
  }catch(e){
    const error=safeError(e),tries=job.retries+1;
    if(tries>=7 || /MISMATCH|NOT_VALIDATED|CONFIGURATION|BLOCKED|UNVERIFIED/.test(error)) {
      await db.batch([
        statement(db,"UPDATE runs SET state='failed',finished_at=?,error=?,lease_until=0 WHERE id=?",new Date().toISOString(),error,job.id),
        statement(db,'UPDATE sources SET active_run=NULL,error=? WHERE provider=? AND active_run=?',error,job.provider,job.id)
      ]);
    }else{
      await run(db,'UPDATE runs SET retries=?,error=?,lease_until=0,lease_owner=NULL WHERE id=?',tries,error,job.id);
      await env.ECCOA_JOBS.send(body,{delaySeconds:Math.min(3600,Math.max(e.retryAfter||0,2**tries*5))});
    }
  }
}
async function crmStep(env,job,c) {
  const s=crmConfig(env),db=env.ECCOA_DB;
  if(!c.phase) {const identity=await verifyWorkspace(env,s);await stage(db,job.id,'identity','crm',identity);return {phase:'contacts',page:1,count:0};}
  if(c.phase==='contacts'){
    const spec={...s.contacts,stageNames:s.stageNames};
    const d=await crmRead(env,'/contacts',{...(spec.params||{}),page:c.page,per_page:spec.perPage||100});
    const p=pageItems(d,spec,c.page);
    if(c.total!==undefined&&c.total!==p.total)throw new Error('CRM_LIST_CHANGED_RETRY');
    const contacts=await Promise.all(p.items.map(raw=>projectContact(raw,spec,env.PSEUDONYM_KEY)));
    await stageMany(db,job.id,'contact',contacts.map(contact=>({key:contact.id,data:contact})));
    const count=c.count+p.items.length;
    if(p.next)return {...c,total:p.total,count,page:p.next};
    const unique=await first(db,"SELECT count(*) n FROM stage WHERE run_id=? AND kind='contact'",job.id);
    if(count!==p.total||unique.n!==p.total)throw new Error('CRM_CONTACT_COVERAGE_INCOMPLETE');
    return {phase:'conversations',page:1,count:0};
  }
  if(c.phase==='conversations'){
    const spec=s.conversations;
    const d=await crmRead(env,'/conversations',{...(spec.params||{}),page:c.page,per_page:spec.perPage||100});
    const p=pageItems(d,spec,c.page);
    if(c.total!==undefined&&c.total!==p.total)throw new Error('CRM_LIST_CHANGED_RETRY');
    const conversations=p.items.map(raw=>{const id=safeId(getPath(raw,spec.id));if(!id)throw new Error('CRM_CONVERSATION_ID_MISSING');return {key:id,data:{id}};});
    await stageMany(db,job.id,'conversation',conversations);
    const count=c.count+p.items.length;
    if(p.next)return {...c,total:p.total,count,page:p.next};
    const unique=await first(db,"SELECT count(*) n FROM stage WHERE run_id=? AND kind='conversation'",job.id);
    if(count!==p.total||unique.n!==p.total)throw new Error('CRM_CONVERSATION_COVERAGE_INCOMPLETE');
    return {phase:'messages',conversationAfter:'',messageCursor:null};
  }
  if(c.phase==='messages'){
    const conv=await first(db,"SELECT key FROM stage WHERE run_id=? AND kind='conversation' AND key>? ORDER BY key LIMIT 1",job.id,c.conversationAfter);
    if(!conv)return {...c,done:true};
    const params={...(s.messages.params||{})};if(c.messageCursor)params[s.messages.cursorParam]=c.messageCursor;
    const data=await crmRead(env,`/conversations/${conv.key}/messages`,params);
    const p=messagePage(data,s.messages);
    const projected=await Promise.all(p.items.map(raw=>projectEvent(raw,s.evidence,env.PSEUDONYM_KEY)));
    await stageMany(db,job.id,'undated',projected.filter(e=>e?.undatedContact).map(e=>({key:e.undatedContact,data:{id:e.undatedContact}})));
    await stageMany(db,job.id,'event',projected.filter(e=>e&&!e.undatedContact).map(e=>({key:e.id,data:e})));
    if(p.next===c.messageCursor&&p.next)throw new Error('CRM_REPEATED_MESSAGE_CURSOR');
    return {...c,messageCursor:p.next||null,conversationAfter:p.next?c.conversationAfter:conv.key};
  }
  throw new Error('CRM_INVALID_CHECKPOINT');
}
async function metaStep(env,job,c){
  const db=env.ECCOA_DB;
  if(!c.phase){
    const identity=await verifyMeta(env);await stage(db,job.id,'identity','meta',identity);
    const source=await first(db,"SELECT confirmed_at FROM sources WHERE provider='meta'");
    return {phase:'ads',after:null,...syncRange(env,source.confirmed_at)};
  }
  if(c.phase==='ads'){
    const p=await adsPage(env,c.after);
    await stageMany(db,job.id,'ad',p.items.map(ad=>({key:ad.id,data:ad})));
    if(p.next===c.after&&p.next)throw new Error('META_REPEATED_CURSOR');
    return p.next?{...c,after:p.next}:{...c,phase:'insights',windowStart:c.start,windowEnd:[addDays(c.start,6),c.end].sort()[0],after:null};
  }
  if(c.phase==='insights'){
    const p=await insightPage(env,c.windowStart,c.windowEnd,c.after);
    await stageMany(db,job.id,'metric',p.items.map(metric=>({key:`${metric.day}:${metric.adId}`,data:metric})));
    if(p.next===c.after&&p.next)throw new Error('META_REPEATED_CURSOR');
    if(p.next)return {...c,after:p.next};
    if(c.windowEnd===c.end)return {...c,done:true};
    return {...c,after:null,windowStart:addDays(c.windowEnd,1),windowEnd:[addDays(c.windowEnd,7),c.end].sort()[0]};
  }
  throw new Error('META_INVALID_CHECKPOINT');
}
async function publishRun(env,job,c){
  const db=env.ECCOA_DB,at=new Date().toISOString(),stmts=[];
  if(job.provider==='crm'){
    stmts.push(statement(db,`INSERT INTO contacts(id,stage_id,stage_name,undated,updated_at)
      SELECT key,json_extract(data,'$.stageId'),json_extract(data,'$.stageName'),json_extract(data,'$.undated'),? FROM stage WHERE run_id=? AND kind='contact'
      ON CONFLICT(id) DO UPDATE SET stage_id=excluded.stage_id,stage_name=excluded.stage_name,undated=excluded.undated,updated_at=excluded.updated_at`,at,job.id));
    stmts.push(statement(db,`INSERT INTO events(id,contact_id,at,day,campaign_id,adset_id,ad_id,evidence)
      SELECT key,json_extract(data,'$.contactId'),json_extract(data,'$.at'),json_extract(data,'$.day'),json_extract(data,'$.campaignId'),json_extract(data,'$.adsetId'),json_extract(data,'$.adId'),json_extract(data,'$.evidence') FROM stage WHERE run_id=? AND kind='event'
      ON CONFLICT(id) DO NOTHING`,job.id));
    stmts.push(statement(db,`INSERT INTO contacts(id,stage_name,undated,updated_at) SELECT key,'Etapa não informada',1,? FROM stage WHERE run_id=? AND kind='undated'
      ON CONFLICT(id) DO UPDATE SET undated=1`,at,job.id));
  }else{
    stmts.push(statement(db,`INSERT INTO ads(id,data) SELECT key,data FROM stage WHERE run_id=? AND kind='ad' ON CONFLICT(id) DO UPDATE SET data=excluded.data`,job.id));
    stmts.push(statement(db,'DELETE FROM metrics WHERE day BETWEEN ? AND ?',c.start,c.end));
    stmts.push(statement(db,`INSERT INTO metrics(day,ad_id,campaign_id,adset_id,data,run_id) SELECT json_extract(data,'$.day'),json_extract(data,'$.adId'),json_extract(data,'$.campaignId'),json_extract(data,'$.adsetId'),data,? FROM stage WHERE run_id=? AND kind='metric'`,job.id,job.id));
    stmts.push(statement(db,`INSERT INTO metric_revisions(run_id,day,ad_id,data,confirmed_at) SELECT ?,json_extract(data,'$.day'),json_extract(data,'$.adId'),data,? FROM stage WHERE run_id=? AND kind='metric' ON CONFLICT DO NOTHING`,job.id,at,job.id));
    // One recursive insert, keeping large historical backfills within D1 batch limits.
    stmts.push(statement(db,`WITH RECURSIVE days(day) AS (SELECT ? UNION ALL SELECT date(day,'+1 day') FROM days WHERE day<?)
      INSERT INTO meta_coverage(day,confirmed_at) SELECT day,? FROM days WHERE true ON CONFLICT(day) DO UPDATE SET confirmed_at=excluded.confirmed_at`,c.start,c.end,at));
  }
  stmts.push(statement(db,"UPDATE runs SET state='completed',finished_at=?,cursor_json=?,lease_until=0,lease_owner=NULL WHERE id=?",at,JSON.stringify(c),job.id));
  stmts.push(statement(db,`UPDATE sources SET active_run=NULL,error=NULL,confirmed_at=?,completed_runs=completed_runs+1,
    identity_json=(SELECT data FROM stage WHERE run_id=? AND kind='identity' LIMIT 1) WHERE provider=? AND active_run=?`,at,job.id,job.provider,job.id));
  // D1 batch is transactional: confirmed data remains untouched on any failure.
  await db.batch(stmts);
}


// src/sync-worker.js

export default {
  async scheduled(event,env,ctx){ctx.waitUntil(startCycle(env,new Date(event.scheduledTime).toISOString()));},
  async queue(batch,env){
    for(const message of batch.messages){try{await processJob(env,message.body);message.ack();}catch{message.retry({delaySeconds:120});}}
  },
  async fetch(){return new Response('Recurso exclusivo de sincronização Eccoa. Sem acesso HTTP.',{status:404,headers:{'Cache-Control':'no-store'}});}
};

